#' Define 10x clonotypes
#'
#' Takes clonality tables generated by `tenx()` and embeds them into Seurat metadata.
#' When `sticky = TRUE`, single-chain cells can inherit the dominant paired clonotype
#' when their chain-specific sequence maps unambiguously to a paired clone above the
#' requested purity threshold.
#'
#' @param seu Seurat. A seurat object to embed with clonality data.
#' @param clonal.list Character. The clonalities to be inserted into the seurat metadata. Default:  `ls(pattern = "^Clonal")`.
#' @param cdr3_map Character. Candidate column names used to map single chains to paired chains. Default: `"cdr3_col2"`.
#' @param purity Numeric. Minimum fraction of the dominant mapped paired to be used in a sticky assignment.
#' @param sticky Logical. If the script should merge the clonality of single chain cells with paired cells.
#' @param stick_only Character vector. Possible values: `TRA`, `TRB`, `TRD`, `TRG`, `IGH`, `IGK`, `IGL`, `all`. Default: `all`
#' @param cell Character. Possible values: `B` Bcells, `T` Tcells, `Tgd` Tcells GamaDelta.
#' @param overwrite Logical. Whether to overwrite clonality columns from seurat.
#'
#' @importFrom stringr str_count
#' @export
add_seurat_metadata <- function(seu = NULL,
                                clonal.list = ls(pattern = "^Clonal", envir = .GlobalEnv),
                                cdr3_map = "cdr3_col2",
                                cell = "T",
                                purity = 0.8,
                                stick_only = "all",
                                sticky = FALSE,
                                overwrite = TRUE) {

  if (is.null(seu)) stop("Please add Seurat object to merge clonality.")

  if (!requireNamespace("Seurat", quietly = TRUE)) {
    stop("This function requires the 'Seurat' package. Install it first.", call. = FALSE)
  }

  cdr3_map <- unique(as.character(cdr3_map))

  bind_named_objects <- function(object_names) {
    if (length(object_names) == 0) {
      return(data.frame())
    }

    dplyr::bind_rows(
      mget(object_names, envir = .GlobalEnv, inherits = FALSE),
      .id = ".clonal_source"
    )
  }

  get_chain_name <- function(source_name) {
    source_name <- sub("^Clonal\\.output\\.10x", "", source_name)
    if (grepl("_", source_name)) {
      return(NA_character_)
    }
    source_name
  }

  get_column_aliases <- function(base_name, chain_name) {
    aliases <- base_name

    if (!is.na(chain_name) && nzchar(chain_name)) {
      aliases <- c(
        aliases,
        paste0(base_name, "_", chain_name)
      )

      if (base_name == "cdr3_col2") {
        aliases <- c(aliases, paste0("cdr3_", chain_name))
      }

      if (base_name %in% c("CDR3", "cdr3_nt")) {
        aliases <- c(aliases, paste0("cdr3_nt_", chain_name))
      }
    }

    unique(aliases)
  }

  match_single_to_pairs <- function(single_row, paired_df, map_candidates, purity) {
    if (nrow(paired_df) == 0) {
      return(list(
        clonality = NA_character_,
        correction = "Not tested",
        mapping_source = NA_character_
      ))
    }

    chain_name <- get_chain_name(single_row[[".clonal_source"]])

    for (map_name in map_candidates) {
      single_cols <- get_column_aliases(map_name, chain_name)
      pair_cols <- get_column_aliases(map_name, chain_name)

      single_col <- intersect(single_cols, names(single_row))[1]
      pair_col <- intersect(pair_cols, names(paired_df))[1]

      if (is.na(single_col) || is.na(pair_col)) {
        next
      }

      single_value <- as.character(single_row[[single_col]])
      if (is.na(single_value) || !nzchar(single_value)) {
        next
      }

      pair_values <- as.character(paired_df[[pair_col]])
      matched <- paired_df[!is.na(pair_values) & grepl(single_value, pair_values, fixed = TRUE), , drop = FALSE]

      if (nrow(matched) == 0) {
        next
      }

      tb <- table(matched[["clonality"]])
      dominant <- names(which.max(tb))[1]
      dominant_purity <- max(tb) / sum(tb)

      if (dominant_purity > purity) {
        correction <- if (identical(as.character(single_row[["clonality"]]), dominant)) "Normal" else "Corrected"

        return(list(
          clonality = dominant,
          correction = correction,
          mapping_source = map_name
        ))
      }
    }

    list(
      clonality = NA_character_,
      correction = "Not tested",
      mapping_source = NA_character_
    )
  }

  singles <- clonal.list[!grepl("_", sub("^Clonal\\.output\\.10x", "", clonal.list))]

  if (!identical(stick_only, "all")) {
    singles <- singles[grepl(stick_only, singles)]
    if (length(singles) == 0) {
      stop(sprintf("No detected %s", stick_only))
    }
  }

  pair_match <- switch(
    cell,
    "B" = c("Clonal.output.10xIGH_IGK", "Clonal.output.10xIGH_IGL"),
    "T" = "Clonal.output.10xTRA_TRB",
    "Tgd" = "Clonal.output.10xTRD_TRG",
    stop("Unsupported cell type. Use 'B', 'T', or 'Tgd'.", call. = FALSE)
  )

  pairs <- clonal.list[clonal.list %in% pair_match]

  if (length(pairs) == 0) {
    stop(sprintf("No paired clonality objects detected for cell type '%s'.", cell), call. = FALSE)
  }

  rest <- setdiff(clonal.list, c(singles, pairs))

  c1 <- bind_named_objects(singles)
  c2 <- bind_named_objects(pairs)
  c3 <- bind_named_objects(rest)

  if (sticky && nrow(c1) > 0 && nrow(c2) > 0) {
    mapped <- lapply(seq_len(nrow(c1)), function(i) {
      match_single_to_pairs(
        single_row = c1[i, , drop = FALSE],
        paired_df = c2,
        map_candidates = cdr3_map,
        purity = purity
      )
    })

    c1$clonality.corrected <- vapply(mapped, `[[`, character(1), "clonality")
    c1$clonality.correction <- vapply(mapped, `[[`, character(1), "correction")
    c1$mapping_source <- vapply(mapped, `[[`, character(1), "mapping_source")
    c1$clonality <- dplyr::coalesce(c1$clonality.corrected, c1$clonality)
    c1$clonality.corrected <- NULL
  }

  if (sticky && nrow(c1) > 0) {
    if (!"clonality.correction" %in% names(c1)) {
      c1$clonality.correction <- "Not tested"
    }
    if (!"mapping_source" %in% names(c1)) {
      c1$mapping_source <- NA_character_
    }
  }

  c0 <- dplyr::bind_rows(c1, c2, c3)

  if (".clonal_source" %in% names(c0)) {
    c0$.clonal_source <- NULL
  }

  c0 <- as.data.frame(c0)
  colnames(c0) <- paste0("Res_", colnames(c0))

  if ("Res_barcodes" %in% colnames(c0)) {
    rownames(c0) <- c0[["Res_barcodes"]]
  }

  if (sticky && "Res_clonality.correction" %in% colnames(c0)) {
    c0$Res_clonality.correction[is.na(c0$Res_clonality.correction)] <- "Not tested"
  }

  if (overwrite) {
    seu@meta.data <- seu@meta.data %>% dplyr::select(-dplyr::contains("Res_"))
  }

  seu <- Seurat::AddMetaData(seu, metadata = c0)
  return(seu)
}
